ed to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-002","topic":"Economic foundations","difficulty":"easy","questionType":"multiple_choice","questionText":"A person starts a bakery, combines workers and equipment, and accepts the risk of the business failing. Which factor of production is this role?","options":["Capital","Enterprise","Land","Labour"],"correctAnswer":"Enterprise","explanation":"Enterprise organises the other factors of production and bears business risk.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","foundations"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.foundations.factors-production","atomicSubskillCode":"econ.foundations.factors-production.classification","evidenceFocusCode":"econ.foundations.factors-production.classification.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Classify enterprise as the factor that organises productive resources and bears business risk."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-003","topic":"Economic foundations","difficulty":"medium","questionType":"multiple_choice","questionText":"A government can fund either a new hospital or a new railway this year. It chooses the hospital. What is the opportunity cost of this decision?","options":["The wages paid to hospital workers","The railway project that is forgone","The total tax revenue collected this year","All future public spending"],"correctAnswer":"The railway project that is forgone","explanation":"Opportunity cost is the next best alternative forgone when a choice is made.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","foundations"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.foundations.opportunity-cost-ppc","atomicSubskillCode":"econ.foundations.opportunity-cost-ppc.opportunity-cost","evidenceFocusCode":"econ.foundations.opportunity-cost-ppc.opportunity-cost.focus.core","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Apply opportunity cost by identifying the next best alternative forgone in a specific economic choice."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.context-application","evidenceFocusCode":"econ.focus.reasoning.application","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Use the details of a specific choice to identify which alternative is genuinely forgone."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-004","topic":"Economic foundations","difficulty":"medium","questionType":"multiple_choice","questionText":"An economy moves from a point inside its production possibility curve to a point on the curve, with no change in the curve itself. What is the best explanation?","options":["Its productive capacity has fallen.","It is using previously underused resources more fully.","It has discovered unlimited resources.","Its opportunity cost has become zero."],"correctAnswer":"It is using previously underused resources more fully.","explanation":"A point inside a PPC represents inefficient or underused resources; moving to the boundary can occur through fuller use of existing capacity.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","foundations"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.foundations.opportunity-cost-ppc","atomicSubskillCode":"econ.foundations.opportunity-cost-ppc.ppc-interpretation","evidenceFocusCode":"econ.foundations.opportunity-cost-ppc.ppc-interpretation.focus.core","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Interpret a movement from inside a production possibility curve to the boundary as improved use of existing productive resources."},{"primarySkillCode":"econ.reasoning.data","atomicSubskillCode":"econ.reasoning.data.diagram","evidenceFocusCode":"econ.focus.reasoning.diagram-causality","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Interpret the economic meaning of positions and movements represented on a production possibility diagram."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-005","topic":"Economic foundations","difficulty":"medium","questionType":"multiple_choice","questionText":"Which change is most likely to improve the quality of labour as a factor of production?","options":["A fall in the number of available workers","More vocational training for workers","A rise in the price of imported machinery","A reduction in the amount of usable land"],"correctAnswer":"More vocational training for workers","explanation":"Training can improve workers' skills and productivity, increasing the quality of labour.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","foundations"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.foundations.factors-production","atomicSubskillCode":"econ.foundations.factors-production.mobility-quality","evidenceFocusCode":"econ.foundations.factors-production.mobility-quality.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how education or training can improve the quality and productivity of labour."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-006","topic":"Markets and resource allocation","difficulty":"easy","questionType":"multiple_choice","questionText":"Other things being equal, what usually happens to quantity demanded when the price of a good rises?","options":["It rises.","It falls.","Demand shifts right.","Demand shifts left."],"correctAnswer":"It falls.","explanation":"The law of demand describes an inverse relationship between a good's own price and quantity demanded, other things equal.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.demand","atomicSubskillCode":"econ.markets.demand.quantity-demanded","evidenceFocusCode":"econ.markets.demand.quantity-demanded.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain the inverse relationship between a good's own price and quantity demanded, other things equal."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-007","topic":"Markets and resource allocation","difficulty":"medium","questionType":"multiple_choice","questionText":"Tea and coffee are substitutes. If the price of coffee rises, what is most likely to happen to the demand for tea, other things equal?","options":["Demand for tea decreases.","Demand for tea increases.","Quantity demanded of tea falls because tea's price rose.","Supply of tea decreases automatically."],"correctAnswer":"Demand for tea increases.","explanation":"When the price of a substitute rises, consumers may switch toward the other good, increasing its demand.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.demand","atomicSubskillCode":"econ.markets.demand.determinants","evidenceFocusCode":"econ.markets.demand.determinants.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how the price of a substitute can change demand for a related good."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-008","topic":"Markets and resource allocation","difficulty":"medium","questionType":"multiple_choice","questionText":"The price of oranges falls while income, tastes and the prices of related goods are unchanged. How should this be shown on a demand diagram for oranges?","options":["A rightward shift of the demand curve","A leftward shift of the demand curve","A movement down along the existing demand curve","A movement up along the existing demand curve"],"correctAnswer":"A movement down along the existing demand curve","explanation":"A change in the good's own price causes a movement along the existing demand curve, not a shift of demand.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.demand","atomicSubskillCode":"econ.markets.demand.shift-movement","evidenceFocusCode":"econ.focus.demand.shift-vs-movement","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Distinguish a movement along demand caused by the good's own price from a shift caused by a non-price determinant."},{"primarySkillCode":"econ.reasoning.data","atomicSubskillCode":"econ.reasoning.data.diagram","evidenceFocusCode":"econ.focus.reasoning.diagram-causality","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Translate a stated market change into the correct movement or shift on a demand diagram."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-009","topic":"Markets and resource allocation","difficulty":"easy","questionType":"multiple_choice","questionText":"Other things being equal, what usually happens to quantity supplied when the market price of a product rises?","options":["It rises.","It falls.","Supply shifts left.","Demand shifts right."],"correctAnswer":"It rises.","explanation":"The law of supply describes a direct relationship between price and quantity supplied, other things equal.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.supply","atomicSubskillCode":"econ.markets.supply.quantity-supplied","evidenceFocusCode":"econ.markets.supply.quantity-supplied.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain the direct relationship between a product's price and quantity supplied, other things equal."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-010","topic":"Markets and resource allocation","difficulty":"medium","questionType":"multiple_choice","questionText":"A clothing manufacturer faces a large rise in wages, while the market price of clothing is unchanged. What is the most likely effect on the supply of clothing?","options":["Supply shifts right because revenue rises.","Supply shifts left because production costs rise.","There is a movement up along the supply curve.","There is a movement down along the supply curve."],"correctAnswer":"Supply shifts left because production costs rise.","explanation":"Higher production costs reduce profitability at each price, shifting the supply curve left.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.supply","atomicSubskillCode":"econ.markets.supply.shift-movement","evidenceFocusCode":"econ.focus.supply.shift-vs-movement","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Apply the distinction between a supply shift caused by production costs and a movement caused by the product's own price."},{"primarySkillCode":"econ.reasoning.data","atomicSubskillCode":"econ.reasoning.data.diagram","evidenceFocusCode":"econ.focus.reasoning.diagram-causality","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Translate a cost change into the correct direction of a supply-curve shift."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-011","topic":"Markets and resource allocation","difficulty":"easy","questionType":"multiple_choice","questionText":"At the market equilibrium price, which condition holds?","options":["Quantity demanded equals quantity supplied.","All consumers can buy as much as they want at zero price.","Firms earn no revenue.","Demand and supply curves cannot shift."],"correctAnswer":"Quantity demanded equals quantity supplied.","explanation":"Market equilibrium occurs where quantity demanded equals quantity supplied.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.equilibrium-price","atomicSubskillCode":"econ.markets.equilibrium-price.equilibrium","evidenceFocusCode":"econ.markets.equilibrium-price.equilibrium.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Identify market equilibrium as the price and quantity at which quantity demanded equals quantity supplied."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-012","topic":"Markets and resource allocation","difficulty":"hard","questionType":"multiple_choice","questionText":"A market price is temporarily below its equilibrium level. What sequence is most likely to move the market back toward equilibrium?","options":["A surplus develops, creating downward pressure on price.","A shortage develops, creating upward pressure on price.","Demand shifts left until quantity demanded is zero.","Supply shifts right because the price is low."],"correctAnswer":"A shortage develops, creating upward pressure on price.","explanation":"Below equilibrium, quantity demanded exceeds quantity supplied. The resulting shortage creates pressure for price to rise.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.equilibrium-price","atomicSubskillCode":"econ.markets.equilibrium-price.disequilibrium-adjustment","evidenceFocusCode":"econ.focus.equilibrium.shortage-surplus","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace how a below-equilibrium price creates a shortage and upward pressure on market price."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Develop the causal chain from disequilibrium to shortage and price adjustment."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-013","topic":"Markets and resource allocation","difficulty":"medium","questionType":"multiple_choice","questionText":"The price of a product rises by 10% and quantity demanded falls by 20%. Using the magnitude of PED, what is the PED?","options":["0.5","1.0","2.0","10.0"],"correctAnswer":"2.0","explanation":"PED magnitude equals percentage change in quantity demanded divided by percentage change in price: 20% ÷ 10% = 2.0.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.ped","atomicSubskillCode":"econ.markets.ped.calculate","evidenceFocusCode":"econ.focus.ped.calculate","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Calculate the magnitude of price elasticity of demand from percentage changes in quantity demanded and price."},{"primarySkillCode":"econ.reasoning.data","atomicSubskillCode":"econ.reasoning.data.calculation","evidenceFocusCode":"econ.reasoning.data.calculation.focus.core","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Carry out a percentage-based economic calculation accurately and interpret the required ratio."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-014","topic":"Markets and resource allocation","difficulty":"easy","questionType":"multiple_choice","questionText":"A product has a PED magnitude of 0.4. How is its demand best described?","options":["Perfectly elastic","Elastic","Unit elastic","Inelastic"],"correctAnswer":"Inelastic","explanation":"A PED magnitude below 1 means quantity demanded is proportionately less responsive than price, so demand is inelastic.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.ped","atomicSubskillCode":"econ.markets.ped.interpret","evidenceFocusCode":"econ.focus.ped.interpret","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Classify demand as elastic, unit elastic or inelastic from the magnitude of the PED coefficient."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-015","topic":"Markets and resource allocation","difficulty":"hard","questionType":"multiple_choice","questionText":"A firm knows demand for its product is price elastic. If the firm cuts its price, what is the most likely effect on total revenue, other things equal?","options":["Total revenue rises because quantity demanded rises proportionately more than price falls.","Total revenue falls because every price cut reduces revenue.","Total revenue is unchanged because demand is elastic.","Total revenue becomes zero."],"correctAnswer":"Total revenue rises because quantity demanded rises proportionately more than price falls.","explanation":"With elastic demand, the proportionate increase in quantity demanded exceeds the proportionate fall in price, so total revenue rises.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.ped","atomicSubskillCode":"econ.markets.ped.revenue","evidenceFocusCode":"econ.focus.ped.revenue","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Apply PED to trace how a price change affects quantity demanded and total revenue."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Connect elasticity to the relative quantity response and then to the direction of total revenue."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-016","topic":"Markets and resource allocation","difficulty":"medium","questionType":"multiple_choice","questionText":"A factory's production creates air pollution that increases healthcare costs for nearby residents. What does this illustrate?","options":["An external cost","An external benefit","A public good","A fall in opportunity cost"],"correctAnswer":"An external cost","explanation":"The factory imposes a cost on third parties who are not part of the market transaction, creating a negative externality.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.market-failure","atomicSubskillCode":"econ.markets.market-failure.externalities","evidenceFocusCode":"econ.focus.market-failure.externalities","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Identify a third-party cost from production as an external cost that can contribute to market failure."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.context-application","evidenceFocusCode":"econ.focus.reasoning.application","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Use stakeholder details in a market scenario to distinguish private effects from third-party effects."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-017","topic":"Markets and resource allocation","difficulty":"hard","questionType":"multiple_choice","questionText":"A government introduces a subsidy for bus operators. Other things equal, which chain is most likely in the bus market?","options":["Operating costs rise → supply falls → fares rise.","Operating costs fall → supply rises → fares tend to fall and quantity tends to rise.","Demand falls → supply becomes perfectly inelastic.","Quantity supplied falls because the subsidy reduces revenue."],"correctAnswer":"Operating costs fall → supply rises → fares tend to fall and quantity tends to rise.","explanation":"A producer subsidy can lower effective production costs, shifting supply right and tending to reduce equilibrium price while raising equilibrium quantity.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","markets"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.markets.intervention","atomicSubskillCode":"econ.markets.intervention.taxes-subsidies","evidenceFocusCode":"econ.markets.intervention.taxes-subsidies.focus.core","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace how a producer subsidy can lower costs, increase supply and affect equilibrium price and quantity."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Build a linked policy chain from subsidy to costs, supply and market outcomes."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-018","topic":"Microeconomic decision-makers","difficulty":"easy","questionType":"multiple_choice","questionText":"Prices in a supermarket allow shoppers to compare the values of different goods. Which function of money does this demonstrate?","options":["Medium of exchange","Store of value","Unit of account","Standard of deferred payment"],"correctAnswer":"Unit of account","explanation":"Money acts as a unit of account when it provides a common measure in which prices and values are expressed.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.money-banking","atomicSubskillCode":"econ.micro.money-banking.money-functions","evidenceFocusCode":"econ.micro.money-banking.money-functions.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain the unit-of-account function of money as a common measure for comparing values and prices."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-019","topic":"Microeconomic decision-makers","difficulty":"easy","questionType":"multiple_choice","questionText":"Which activity is a typical role of a commercial bank?","options":["Setting all market prices in the economy","Accepting deposits and providing loans","Deciding the government's tax rates","Producing every country's banknotes"],"correctAnswer":"Accepting deposits and providing loans","explanation":"Commercial banks commonly accept deposits and provide credit to households and firms.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.money-banking","atomicSubskillCode":"econ.micro.money-banking.financial-institutions","evidenceFocusCode":"econ.micro.money-banking.financial-institutions.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Identify deposit-taking and lending as core functions of commercial banks."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-020","topic":"Microeconomic decision-makers","difficulty":"medium","questionType":"multiple_choice","questionText":"Market interest rates rise substantially. Which household response is most likely, other things equal?","options":["Saving becomes less attractive and borrowing becomes cheaper.","Saving becomes more attractive and borrowing becomes more expensive.","Both saving and borrowing become costless.","Interest rates no longer affect household choices."],"correctAnswer":"Saving becomes more attractive and borrowing becomes more expensive.","explanation":"Higher interest rates increase the reward to saving and the cost of borrowing, which can change household consumption and saving choices.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.households","atomicSubskillCode":"econ.micro.households.borrowing-interest","evidenceFocusCode":"econ.micro.households.borrowing-interest.focus.core","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Apply an interest-rate change to household incentives to save, borrow and spend."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-021","topic":"Microeconomic decision-makers","difficulty":"hard","questionType":"multiple_choice","questionText":"Demand for qualified software engineers rises while the supply of qualified engineers is unchanged. What is the most likely effect in that labour market?","options":["The equilibrium wage falls.","The equilibrium wage rises.","The supply of engineers immediately becomes zero.","The demand for engineers shifts left."],"correctAnswer":"The equilibrium wage rises.","explanation":"An increase in labour demand with unchanged labour supply creates upward pressure on the equilibrium wage.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.labour","atomicSubskillCode":"econ.micro.labour.wage-determination","evidenceFocusCode":"econ.focus.labour.wage-demand-supply","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace how an increase in labour demand, with labour supply unchanged, affects the equilibrium wage."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Develop the causal chain from a labour-demand shift to wage adjustment."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-022","topic":"Microeconomic decision-makers","difficulty":"medium","questionType":"multiple_choice","questionText":"Why might a dangerous occupation pay a higher wage than a similar safer occupation, other things equal?","options":["Workers may require compensation for worse non-monetary working conditions.","Danger always makes labour supply perfectly elastic.","Danger removes the need for skills.","Firms in dangerous industries cannot earn revenue."],"correctAnswer":"Workers may require compensation for worse non-monetary working conditions.","explanation":"Non-monetary job characteristics can affect labour supply and wage differentials; unpleasant or risky conditions may require higher pay to attract workers.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.labour","atomicSubskillCode":"econ.micro.labour.wage-differences","evidenceFocusCode":"econ.micro.labour.wage-differences.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how non-monetary working conditions can contribute to wage differences between occupations."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-023","topic":"Microeconomic decision-makers","difficulty":"medium","questionType":"multiple_choice","questionText":"How can division of labour raise productivity?","options":["Workers repeatedly perform specialised tasks and can become faster or more skilled at them.","Every worker produces every stage of the product alone.","Firms stop using capital equipment.","Specialisation eliminates all production costs."],"correctAnswer":"Workers repeatedly perform specialised tasks and can become faster or more skilled at them.","explanation":"Specialisation can increase skill, speed and efficiency through repetition and task focus.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.firms-production","atomicSubskillCode":"econ.micro.firms-production.specialisation-productivity","evidenceFocusCode":"econ.micro.firms-production.specialisation-productivity.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how division of labour and task specialisation can increase worker productivity."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-024","topic":"Microeconomic decision-makers","difficulty":"medium","questionType":"multiple_choice","questionText":"A firm has total revenue of $80 000 and total costs of $65 000. What is its profit?","options":["$15 000","$65 000","$80 000","$145 000"],"correctAnswer":"$15 000","explanation":"Profit equals total revenue minus total cost: $80 000 − $65 000 = $15 000.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","micro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.micro.costs-revenue-objectives","atomicSubskillCode":"econ.micro.costs-revenue-objectives.revenue-profit","evidenceFocusCode":"econ.micro.costs-revenue-objectives.revenue-profit.focus.core","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Calculate profit as total revenue minus total cost."},{"primarySkillCode":"econ.reasoning.data","atomicSubskillCode":"econ.reasoning.data.calculation","evidenceFocusCode":"econ.reasoning.data.calculation.focus.core","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Carry out a simple economic calculation accurately using supplied financial data."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-025","topic":"Government and the macroeconomy","difficulty":"easy","questionType":"multiple_choice","questionText":"Which macroeconomic objective is most directly concerned with keeping the general price level from rising rapidly?","options":["Price stability","A current-account deficit","Higher unemployment","Lower labour productivity"],"correctAnswer":"Price stability","explanation":"Price stability concerns maintaining a low and stable rate of inflation.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.policy","atomicSubskillCode":"econ.macro.policy.objectives-conflicts","evidenceFocusCode":"econ.macro.policy.objectives-conflicts.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Identify price stability as the macroeconomic objective concerned with low and stable inflation."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-026","topic":"Government and the macroeconomy","difficulty":"hard","questionType":"multiple_choice","questionText":"During a recession, a government increases spending on infrastructure without raising taxes. Which chain is most likely in the short run, other things equal?","options":["Aggregate demand falls → output falls → unemployment falls.","Aggregate demand rises → output may rise → unemployment may fall.","Aggregate supply becomes zero → prices must fall.","Imports disappear → the exchange rate becomes fixed."],"correctAnswer":"Aggregate demand rises → output may rise → unemployment may fall.","explanation":"Higher government spending is an expansionary fiscal action that can raise aggregate demand, supporting output and employment when spare capacity exists.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.policy","atomicSubskillCode":"econ.macro.policy.fiscal","evidenceFocusCode":"econ.focus.fiscal.transmission","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace an increase in government spending through aggregate demand to likely output and employment effects."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Develop a multi-step fiscal-policy transmission chain from the policy instrument to macroeconomic outcomes."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-027","topic":"Government and the macroeconomy","difficulty":"hard","questionType":"multiple_choice","questionText":"A central bank raises interest rates to reduce inflationary pressure. Which transmission chain is most likely?","options":["Borrowing becomes cheaper → spending rises → aggregate demand rises.","Borrowing becomes more expensive → consumption and investment may fall → aggregate demand may fall.","Saving becomes less attractive → spending must rise.","Productive capacity immediately doubles."],"correctAnswer":"Borrowing becomes more expensive → consumption and investment may fall → aggregate demand may fall.","explanation":"Higher interest rates raise borrowing costs and can encourage saving, reducing consumption and investment and therefore aggregate demand.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.policy","atomicSubskillCode":"econ.macro.policy.monetary","evidenceFocusCode":"econ.focus.monetary.interest-rate-chain","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace a rise in interest rates through borrowing, consumption and investment to aggregate demand."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Develop the interest-rate transmission mechanism as a connected causal chain."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-028","topic":"Government and the macroeconomy","difficulty":"hard","questionType":"multiple_choice","questionText":"A government funds training programmes that improve workers' skills. What is the most likely long-run supply-side effect?","options":["Lower labour productivity and lower productive capacity","Higher labour productivity and greater productive capacity","A guaranteed fall in every market price","An immediate elimination of all unemployment"],"correctAnswer":"Higher labour productivity and greater productive capacity","explanation":"Better skills can raise labour productivity and the economy's productive capacity, although the effect may take time.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.policy","atomicSubskillCode":"econ.macro.policy.supply-side","evidenceFocusCode":"econ.focus.supply-side.capacity","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace worker training through productivity to greater productive capacity in the longer run."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Connect a supply-side intervention to productivity and productive-capacity outcomes."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-029","topic":"Government and the macroeconomy","difficulty":"easy","questionType":"multiple_choice","questionText":"Which change most directly indicates economic growth?","options":["An increase in real GDP","An increase in the general price level with unchanged real output","A fall in the money wage rate","A rise in unemployment with unchanged output"],"correctAnswer":"An increase in real GDP","explanation":"Economic growth is normally measured by an increase in real output, commonly real GDP.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.growth","atomicSubskillCode":"econ.macro.growth.measurement-causes","evidenceFocusCode":"econ.macro.growth.measurement-causes.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Identify an increase in real GDP as a standard measure of economic growth."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-030","topic":"Government and the macroeconomy","difficulty":"medium","questionType":"multiple_choice","questionText":"New technology makes some routine factory jobs unnecessary, but unemployed workers do not yet have the skills needed for new technical jobs. Which type of unemployment is this?","options":["Frictional","Structural","Seasonal","Voluntary only"],"correctAnswer":"Structural","explanation":"Structural unemployment occurs when the pattern of labour demand changes and workers' skills or locations do not match available jobs.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.employment","atomicSubskillCode":"econ.macro.employment.causes-types","evidenceFocusCode":"econ.focus.unemployment.types","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Distinguish structural unemployment by identifying a mismatch between workers' skills and changing labour demand."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-031","topic":"Government and the macroeconomy","difficulty":"medium","questionType":"multiple_choice","questionText":"World oil prices rise sharply and firms across an economy face higher transport and production costs. What type of inflationary pressure is most directly created?","options":["Demand-pull inflation","Cost-push inflation","Deflation caused by excess supply","Inflation caused only by lower taxes"],"correctAnswer":"Cost-push inflation","explanation":"Higher input costs can push firms' costs upward across the economy, creating cost-push inflationary pressure.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","macro"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.macro.inflation","atomicSubskillCode":"econ.macro.inflation.causes","evidenceFocusCode":"econ.focus.inflation.demand-cost","assessmentProcessCode":"BH-AO2","cognitiveProcess":"apply","evidenceStatement":"Apply the distinction between demand-pull and cost-push inflation to a rise in economy-wide production costs."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.context-application","evidenceFocusCode":"econ.focus.reasoning.application","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Use the source of a real-economy cost shock to identify the relevant inflation mechanism."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-032","topic":"Economic development","difficulty":"easy","questionType":"multiple_choice","questionText":"Which indicator adjusts total output for population size when comparing average material living standards between countries?","options":["Real GDP per head","Total nominal GDP only","The inflation rate only","The exchange rate only"],"correctAnswer":"Real GDP per head","explanation":"Real GDP per head relates real output to population size and is often used as an indicator of average material living standards.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","development"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.development.living-standards","atomicSubskillCode":"econ.development.living-standards.income-output-indicators","evidenceFocusCode":"econ.development.living-standards.income-output-indicators.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Identify real GDP per head as an income-output indicator that adjusts real output for population size."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-033","topic":"Economic development","difficulty":"easy","questionType":"multiple_choice","questionText":"Which is a non-income indicator that can help compare living standards?","options":["Life expectancy","The market exchange rate alone","A firm's total revenue","The price of one imported good"],"correctAnswer":"Life expectancy","explanation":"Life expectancy captures an important health outcome and can complement income-based measures of living standards.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","development"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.development.living-standards","atomicSubskillCode":"econ.development.living-standards.non-income-indicators","evidenceFocusCode":"econ.development.living-standards.non-income-indicators.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Identify health and education measures such as life expectancy as non-income indicators of living standards."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-034","topic":"Economic development","difficulty":"hard","questionType":"multiple_choice","questionText":"Country A has a higher real GDP per head than Country B. Why is it unsafe to conclude from this fact alone that everyone in Country A has a higher living standard?","options":["Real GDP per head can hide differences in income distribution and non-income wellbeing.","Real GDP per head is always measured in kilograms.","A higher real GDP per head proves unemployment is zero.","Income never affects material consumption."],"correctAnswer":"Real GDP per head can hide differences in income distribution and non-income wellbeing.","explanation":"An average income-output measure does not show how income is distributed and does not capture every dimension of wellbeing.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","development"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.development.living-standards","atomicSubskillCode":"econ.development.living-standards.measurement-limitations","evidenceFocusCode":"econ.focus.living-standards.indicator-limits","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Analyse why a higher real GDP per head alone cannot establish that every person has a higher living standard."},{"primarySkillCode":"econ.reasoning.evaluation","atomicSubskillCode":"econ.reasoning.evaluation.conditions","evidenceFocusCode":"econ.focus.reasoning.depends-on","assessmentProcessCode":"BH-AO4","cognitiveProcess":"evaluate","evidenceStatement":"Recognise that a living-standard judgement depends on distribution and non-income conditions, not one average indicator alone."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-035","topic":"Economic development","difficulty":"hard","questionType":"multiple_choice","questionText":"A low-income region has poor school attendance, low worker skills and low productivity. Which chain best explains how this may help poverty persist?","options":["Low skills → low productivity → low earning potential → continued poverty","Low skills → higher productivity → higher incomes → continued poverty","Poor attendance → unlimited resources → no scarcity","Low productivity → automatic full employment → higher incomes"],"correctAnswer":"Low skills → low productivity → low earning potential → continued poverty","explanation":"Low human capital can reduce productivity and earning opportunities, which can reinforce poverty over time.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","development"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.development.poverty","atomicSubskillCode":"econ.development.poverty.causes-consequences","evidenceFocusCode":"econ.development.poverty.causes-consequences.focus.core","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace how low education or skills can reduce productivity and income, contributing to persistent poverty."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Develop a multi-step causal chain linking human capital, productivity, income and poverty."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-036","topic":"Economic development","difficulty":"medium","questionType":"multiple_choice","questionText":"What is a likely economic effect of a sustained rise in the share of elderly people in a country's population, other things equal?","options":["A higher dependency ratio","A guaranteed fall in life expectancy","An automatic increase in the birth rate","The elimination of government spending on healthcare"],"correctAnswer":"A higher dependency ratio","explanation":"Population ageing can raise the proportion of dependants relative to the working-age population.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","development"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.development.population","atomicSubskillCode":"econ.development.population.structure-change","evidenceFocusCode":"econ.development.population.structure-change.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how population ageing can increase the dependency ratio."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-037","topic":"International trade and globalisation","difficulty":"medium","questionType":"multiple_choice","questionText":"Why can international specialisation increase total output?","options":["Countries can concentrate more resources on goods they can produce at lower opportunity cost and trade for others.","Trade makes every country's opportunity costs identical.","Specialisation guarantees that no workers ever lose jobs.","Countries no longer face scarcity after specialising."],"correctAnswer":"Countries can concentrate more resources on goods they can produce at lower opportunity cost and trade for others.","explanation":"Specialisation based on relative opportunity costs can allow resources to be used more efficiently and increase combined output.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","international"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.international.specialisation-trade","atomicSubskillCode":"econ.international.specialisation-trade.specialisation","evidenceFocusCode":"econ.international.specialisation-trade.specialisation.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how specialisation according to relative opportunity cost can raise combined output and support trade."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-038","topic":"International trade and globalisation","difficulty":"medium","questionType":"multiple_choice","questionText":"What is the direct effect of a tariff on an imported product, other things equal?","options":["It raises the cost of importing the product and can protect domestic producers.","It guarantees the domestic currency appreciates.","It removes all government revenue.","It makes the imported product free to consumers."],"correctAnswer":"It raises the cost of importing the product and can protect domestic producers.","explanation":"A tariff is a tax on imports. It raises the cost of imported goods and can make domestic alternatives more competitive.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","international"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.international.globalisation-restrictions","atomicSubskillCode":"econ.international.globalisation-restrictions.trade-barriers","evidenceFocusCode":"econ.international.globalisation-restrictions.trade-barriers.focus.core","assessmentProcessCode":"BH-AO1","cognitiveProcess":"understand","evidenceStatement":"Explain how an import tariff raises the cost of imported goods and can protect domestic producers."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO1","assessmentObjectives":["AO1"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-039","topic":"International trade and globalisation","difficulty":"hard","questionType":"multiple_choice","questionText":"A country's currency appreciates against its main trading partners. What is the most likely immediate price effect, other things equal?","options":["Imports become cheaper in domestic currency and exports become more expensive to foreign buyers.","Imports become more expensive in domestic currency and exports become cheaper to foreign buyers.","Both imports and exports become free.","The prices of imports and exports cannot be affected by exchange rates."],"correctAnswer":"Imports become cheaper in domestic currency and exports become more expensive to foreign buyers.","explanation":"An appreciation raises the currency's external value, making foreign goods cheaper to domestic buyers and domestic goods more expensive in foreign currency.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","international"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.international.exchange-rates","atomicSubskillCode":"econ.international.exchange-rates.appreciation-depreciation","evidenceFocusCode":"econ.focus.exchange-rate.direction-effects","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace an appreciation through the domestic-currency price of imports and the foreign-currency price of exports."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Build the exchange-rate chain from appreciation to import and export price effects."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}},{"externalId":"bh-econ-0455-p1-v1-040","topic":"International trade and globalisation","difficulty":"hard","questionType":"multiple_choice","questionText":"Domestic incomes rise rapidly while foreign incomes and the exchange rate are unchanged. Which effect is most likely on the current account, other things equal?","options":["Import demand rises, which may worsen the current-account balance.","Import demand falls to zero, which must improve the current account.","Export prices automatically fall because domestic income rose.","The current account cannot be affected by domestic income."],"correctAnswer":"Import demand rises, which may worsen the current-account balance.","explanation":"Higher domestic income can increase demand for imports. If other factors are unchanged, higher import spending can weaken the current-account balance.","hints":[],"timeLimit":90,"points":1,"tags":["economics","igcse","0455","paper-1","international"],"language":"en","eligibleGrades":[10,11],"taxonomies":[{"primarySkillCode":"econ.international.current-account","atomicSubskillCode":"econ.international.current-account.imbalance","evidenceFocusCode":"econ.focus.current-account.causal-chain","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Trace how rising domestic income can increase import demand and contribute to a weaker current-account balance."},{"primarySkillCode":"econ.reasoning.analysis","atomicSubskillCode":"econ.reasoning.analysis.causal-chain","evidenceFocusCode":"econ.focus.reasoning.chain-development","assessmentProcessCode":"BH-AO3","cognitiveProcess":"analyze","evidenceStatement":"Develop the causal chain from domestic income growth to import demand and the current-account balance."}],"assessmentProfile":{"providerName":"Cambridge International Education","programmeCode":"0455","sourceVersion":"2027-2029","paperComponent":"paper_1","paperSection":null,"evidenceMode":"mcq","primaryAssessmentObjective":"AO2","assessmentObjectives":["AO2"],"sourceReference":"Brains Heist original Paper 1 readiness diagnostic aligned to the public Cambridge IGCSE Economics 0455 2027–2029 assessment structure."}}]}$package$::jsonb,
    false
  ) into v_result;

  if coalesce((v_result->>'success')::boolean,false) is not true then
    raise exception 'economics_paper1_v1_import_failed';
  end if;

  select id,question_count,taxonomy_count,assessment_profile_count
  into v_release_id,v_question_count,v_taxonomy_count,v_profile_count
  from public.registry_verified_question_import_releases
  where package_id='economics-0455-paper1-readiness-v1'
    and package_version='1.0.0';

  if v_release_id is null or v_question_count<>40 or v_taxonomy_count<>59 or v_profile_count<>40 then
    raise exception 'economics_paper1_v1_release_incomplete q=% taxonomy=% profiles=%',
      v_question_count,v_taxonomy_count,v_profile_count;
  end if;

  select
    count(*) filter(where p.primary_assessment_objective='AO1'),
    count(*) filter(where p.primary_assessment_objective='AO2')
  into v_ao1,v_ao2
  from public.questions q
  join public.verified_question_assessment_profiles p
    on p.question_id=q.id
   and p.question_content_hash=q.current_content_hash
   and p.status='active'
  where q.verified_external_id like 'bh-econ-0455-p1-v1-%'
    and q.content_origin='brain_heist'
    and q.verification_status='verified'
    and q.analytics_eligible
    and p.programme_code='0455'
    and p.source_version='2027-2029'
    and p.paper_component='paper_1';

  if v_ao1<>20 or v_ao2<>20 then
    raise exception 'economics_paper1_v1_ao_distribution_invalid ao1=% ao2=%',v_ao1,v_ao2;
  end if;

  select count(distinct strand.code)
  into v_content_strands
  from public.questions q
  join public.verified_question_registry_taxonomy tx
    on tx.question_id=q.id
   and tx.question_content_hash=q.current_content_hash
   and tx.review_status='approved'
   and not tx.human_review_required
  join public.academic_skill_registry_nodes skill on skill.id=tx.primary_skill_node_id
  join public.academic_skill_registry_nodes strand on strand.id=skill.parent_id
  where q.verified_external_id like 'bh-econ-0455-p1-v1-%'
    and strand.node_type='strand'
    and strand.code in ('econ.foundations','econ.markets','econ.micro','econ.macro','econ.development','econ.international');

  if v_content_strands<>6 then
    raise exception 'economics_paper1_v1_content_strand_coverage_invalid strands=%',v_content_strands;
  end if;

  if exists(
    select 1
    from public.questions q
    where q.verified_external_id like 'bh-econ-0455-p1-v1-%'
      and (
        q.subject<>'Economics'
        or q.academic_subject_id<>(select id from public.academic_subjects where code='economics')
        or q.eligible_grade_levels<>array[10,11]::smallint[]
        or q.question_type<>'multiple_choice'
        or q.points<>1
        or q.content_origin<>'brain_heist'
        or q.pool_scope<>'global'
        or q.verification_status<>'verified'
        or not q.analytics_eligible
        or not q.is_public
        or q.current_content_hash<>q.verified_content_hash
      )
  ) then
    raise exception 'economics_paper1_v1_question_authority_invariant_failed';
  end if;

  if exists(
    select 1
    from public.questions q
    where q.verified_external_id like 'bh-econ-0455-p1-v1-%'
      and not exists(
        select 1
        from public.verified_question_registry_taxonomy tx
        where tx.question_id=q.id
          and tx.question_content_hash=q.current_content_hash
          and tx.review_status='approved'
          and not tx.human_review_required
      )
  ) then
    raise exception 'economics_paper1_v1_missing_registry_taxonomy';
  end if;
end;
$migration$;
